// ⚠️ `refunds.amount` 与 `orders.amount_refunded` 是**两个不同的量**（0016 的列 COMMENT）：
//
//	前者是退款总额的唯一真相源，后者只记真的退出去的现金（destination='original'）。
//	退到余额时 `amount_refunded` 恒为 0 —— 拿它当「退了多少」会在对账页上少算一大截。
func (q *Queries) AdminGetOrder(ctx context.Context, tradeNo string) (AdminGetOrderRow, error) {
	row := q.db.QueryRow(ctx, adminGetOrder, tradeNo)
	var i AdminGetOrderRow
	err := row.Scan(
		&i.ID,
		&i.TradeNo,
		&i.UserID,
		&i.Type,
		&i.Status,
		&i.PlanID,
		&i.Period,
		&i.Currency,
		&i.AmountGross,
		&i.AmountDiscount,
		&i.SurplusAmount,
		&i.AmountBalance,
		&i.AmountDue,
		&i.AmountPaid,
		&i.AmountRefunded,
		&i.SurplusOrderIds,
		&i.CouponID,
		&i.InvitedBy,
		&i.Gateway,
		&i.GatewayRef,
		&i.PayChain,
		&i.PayAddress,
		&i.PayAmountUsdt6,
		&i.PayAmountReceived,
		&i.PayFromAddress,
		&i.FxUsdtPerCny,
		&i.FxLockedAt,
		&i.ExpiresAt,
		&i.AddressWatchUntil,
		&i.PaidAt,
		&i.CompletedAt,
		&i.CancelledAt,
		&i.CoversFrom,
		&i.CoversTo,
		&i.PrevOrderID,
		&i.PriceMonthlyAtOrder,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UserEmail,
		&i.PlanName,
		&i.PaymentCount,
		&i.ReceivedUsdt6,
		&i.RefundedToBalance,
	)
	return i, err
}

